        "code": "import * as ApexRuntime from 'apexify.js';\nimport { mkdir, writeFile, readFile, access } from 'node:fs/promises';\nimport { fileURLToPath, pathToFileURL } from 'node:url';\nimport path from 'node:path';\nimport assert from 'node:assert/strict';\n\nconst Apex = ApexRuntime;\nconst ApexPainter = ApexRuntime.ApexPainter;\nconst ApexifyDecodeError = ApexRuntime.ApexifyDecodeError;\nconst painter = new ApexPainter({ type: 'buffer' });\n\n// This is the actual Peak Lab recipe.\n// Supporting drawing/chart/audio helpers used by this recipe are on the next code pages.\nasync function main() {\n  const layers=heading('04 / PARAMETRIC CARTOGRAPHY','A field of echoes','A synthetic terrain. Contours are computed from harmonic radial fields.');\n    for(let k=0;k<76;k++){\n      const r=35+k*5.5;\n      const pts=Array.from({length:241},(_,j) =>{const a=j/240*TAU;const d=r*(1+.12*Math.sin(3*a+k*.045)+.065*Math.cos(7*a-k*.025));return polar(760,680,d,a);});\n      layers.push(line(pts,k%6===0?COLORS.red:'#325e62',k%6===0?2.2:.8,{opacity:k%6===0?.95:.55}));\n    }\n    layers.push(textLayer(txt('RESONANCE\\nINDEX 079',92,266,16,COLORS.ink,{font:font(16,'mono'),layout:{lineHeight:1.5}}),txt('ECHO / 01',970,1020,30,COLORS.ink,{font:font(30,'serif')})));\n    let art=await scene(1440,1160,layers);\n    const mark=painter.path2d.create([{type:'circle',x:760,y:680,radius:27},{type:'circle',x:760,y:680,radius:9}]);\n    art=await painter.path2d.draw(art,mark,{fill:{color:COLORS.red,rule:'evenodd'},stroke:{color:COLORS.ink,width:1}});\n    art=await painter.path2d.custom([\n      {startCoordinates:{x:180,y:395},endCoordinates:{x:704,y:632},path:{type:'bezier',tension:.4},arrow:{end:true,size:12},markers:[{position:.35,shape:'diamond',size:7,color:COLORS.red}],lineStyle:{width:1.5,color:COLORS.ink,lineDash:{dashArray:[5,5]}}},\n      {startCoordinates:{x:1190,y:450},endCoordinates:{x:969,y:600},path:{type:'smooth'},arrow:{end:true},lineStyle:{width:1.5,color:COLORS.red}}\n    ],art);\n    return [await save('04-paths.png',art)];\n}"
