        "code": "import * as ApexRuntime from 'apexify.js';\nimport { mkdir, writeFile, readFile, access } from 'node:fs/promises';\nimport { fileURLToPath, pathToFileURL } from 'node:url';\nimport path from 'node:path';\nimport assert from 'node:assert/strict';\n\nconst Apex = ApexRuntime;\nconst ApexPainter = ApexRuntime.ApexPainter;\nconst ApexifyDecodeError = ApexRuntime.ApexifyDecodeError;\nconst painter = new ApexPainter({ type: 'buffer' });\n\n// This is the actual Peak Lab recipe.\n// Supporting drawing/chart/audio helpers used by this recipe are on the next code pages.\nasync function main() {\n  const w=900,h=640,base=await painter.createCanvas({width:w,height:h,colorBg:'#000000'});\n    const pixels=await painter.pixels.getData(base);\n    for(let y=0;y<h;y++)for(let x=0;x<w;x++){\n      const u=(x-w/2)/h,v=(y-h/2)/h;\n      const d1=Math.hypot(u+.21,v),d2=Math.hypot(u-.22,v-.1);\n      const f=Math.sin(d1*62)+Math.cos(d2*54)+Math.sin((u+v)*16);\n      const k=(Math.atan(f*1.8)/Math.PI+.5);\n      const index=(y*w+x)*4;\n      pixels.data[index]=Math.round(18+225*Math.pow(k,1.8));\n      pixels.data[index+1]=Math.round(20+190*Math.sin(k*Math.PI)*.8);\n      pixels.data[index+2]=Math.round(35+195*(1-k));pixels.data[index+3]=255;\n    }\n    const original=await painter.pixels.setData(base,pixels);\n    let treated=await painter.pixels.manipulate(original,{region:{x:0,y:0,width:w,height:h},processor:(r,g,b,a,x,y) =>{\n      const vignette=Math.max(.25,1-Math.hypot((x-w/2)/w,(y-h/2)/h)*.9);\n      return [r*vignette,g*vignette,b*vignette,a];\n    }});\n    treated=await painter.pixels.setColor(treated,2,2,{r:255,g:255,b:255,a:255});\n    const sample=await painter.pixels.getColor(treated,2,2);\n    const monochrome=await painter.pixels.manipulate(original,{filter:'grayscale',intensity:1});\n    const layers=heading('05 / FIELD RESEARCH','Interference atlas','Two wave sources. Pixel-level synthesis. No external rendering engine.');\n    layers.push({type:'imageBuffer',buffer:treated,x:64,y:246,width:930,height:661},{type:'imageBuffer',buffer:monochrome,x:1022,y:246,width:354,height:252});\n    layers.push(textLayer(txt('CONSTRUCTIVE\\n& DESTRUCTIVE\\nINTERFERENCE',1022,532,20,COLORS.ink,{font:font(20,'bold'),layout:{lineHeight:1.4}}),txt('FIELD 05\\n900 × 640 SAMPLES\\nRGBA / 8 BIT',1022,670,15,COLORS.muted,{font:font(15,'mono'),layout:{lineHeight:1.6}})));\n    for(let i=0;i<20;i++)layers.push(images(rect(1022+i*17.7,825,18,48,`rgb(${18+i*11},${30+i*6},${230-i*9})`)));\n    return [await save('05-pixels.png',await scene(1440,970,layers)),await save('05-field-source.png',treated),await json('05-pixel-sample.json',sample)];\n}"
