        "code": "import * as ApexRuntime from 'apexify.js';\nimport { mkdir, writeFile, readFile, access } from 'node:fs/promises';\nimport { fileURLToPath, pathToFileURL } from 'node:url';\nimport path from 'node:path';\nimport assert from 'node:assert/strict';\n\nconst Apex = ApexRuntime;\nconst ApexPainter = ApexRuntime.ApexPainter;\nconst ApexifyDecodeError = ApexRuntime.ApexifyDecodeError;\nconst painter = new ApexPainter({ type: 'buffer' });\n\n// This is the actual Peak Lab recipe.\n// Supporting drawing/chart/audio helpers used by this recipe are on the next code pages.\nasync function main() {\n  const src=await plate(360,230),sourceName='07-filter-source.png';await save(sourceName,src);\n    const filters=[{type:'gaussianBlur',intensity:4},{type:'motionBlur',intensity:11,angle:25},{type:'radialBlur',intensity:12},{type:'sharpen',intensity:2},{type:'noise',intensity:.25},{type:'grain',intensity:.3},{type:'edgeDetection'},{type:'emboss'},{type:'invert'},{type:'grayscale'},{type:'sepia'},{type:'pixelate',size:12},{type:'brightness',value:30},{type:'contrast',value:40},{type:'saturation',value:60},{type:'hueShift',value:100},{type:'posterize',levels:5}];\n    const layers=heading('07 / IMAGE LAB','Eighteen ways to see','Original plus the complete filter family. Each treatment is generated independently.');\n    for(const item of filters){\n      if(['edgeDetection','emboss'].includes(item.type))item.intensity=1;\n      // image.effects brightness is -1..1; contrast is -255..254.\n      // createImage.filters uses percentages for both; these contracts differ.\n      if(item.type==='brightness')item.value/=100;\n    }\n    const all=[{type:'original'},...filters],knownIssues=[];\n    for(let i=0;i<all.length;i++){\n      const item=all[i],x=64+(i%3)*450,y=244+Math.floor(i/3)*330;\n      let buffer=src,fallback=false;\n      if(i)try{buffer=await painter.image.effects(path.join(OUT,sourceName),[item]);}catch(error){\n        // Pinned upstream filter bug: grayscale emits a single-channel raw raster,\n        // but the filter pipeline requires four channels. Do not hide this failure.\n        if(!(error instanceof ApexifyDecodeError)||!['grayscale','edgeDetection'].includes(item.type)||!error.message.includes('geometry'))throw error;\n        fallback=true;knownIssues.push({feature:item.type,error:error.message,alternative:'Explicit painter.pixels implementation'});\n        if(item.type==='grayscale')buffer=await painter.pixels.manipulate(src,{filter:'grayscale'});\n        else{\n          const pix=await painter.pixels.getData(src),copy=new Uint8ClampedArray(pix.data),w=pix.width,h=pix.height;\n          const luminance=(x,y) =>{const n=(y*w+x)*4;return .2126*copy[n]+.7152*copy[n+1]+.0722*copy[n+2];};\n          for(let y=1;y<h-1;y++)for(let x=1;x<w-1;x++){\n            const gx=-luminance(x-1,y-1)+luminance(x+1,y-1)-2*luminance(x-1,y)+2*luminance(x+1,y)-luminance(x-1,y+1)+luminance(x+1,y+1);\n            const gy=-luminance(x-1,y-1)-2*luminance(x,y-1)-luminance(x+1,y-1)+luminance(x-1,y+1)+2*luminance(x,y+1)+luminance(x+1,y+1);\n            const n=(y*w+x)*4,m=Math.min(255,Math.hypot(gx,gy));pix.data[n]=pix.data[n+1]=pix.data[n+2]=m;\n          }\n          buffer=await painter.pixels.setData(src,pix);\n        }\n      }\n      layers.push({type:'imageBuffer',buffer,x,y,width:412,height:264},textLayer(txt(item.type+(fallback?' *':''),x,y+278,19,COLORS.ink,{font:font(19,'mono')})));\n    }\n    layers.push(textLayer(txt('* Upstream channel error reproduced; displayed result uses the documented pixel-based alternative.',64,2220,14,COLORS.red)));\n    return [await save('07-filters.png',await scene(1440,2290,layers)),await json('07-known-filter-issues.json',knownIssues)];\n}"
