        "label": "Recipe 09",
        "language": "ts",
        "code": "import * as ApexRuntime from 'apexify.js';\nimport { mkdir, writeFile, readFile, access } from 'node:fs/promises';\nimport { fileURLToPath, pathToFileURL } from 'node:url';\nimport path from 'node:path';\nimport assert from 'node:assert/strict';\n\nconst Apex = ApexRuntime;\nconst ApexPainter = ApexRuntime.ApexPainter;\nconst ApexifyDecodeError = ApexRuntime.ApexifyDecodeError;\nconst painter = new ApexPainter({ type: 'buffer' });\n\n// This is the actual Peak Lab recipe.\n// Supporting drawing/chart/audio helpers used by this recipe are on the next code pages.\nasync function main() {\n  const src=await plate(600,400);await save('09-source.png',src);const source=path.join(OUT,'09-source.png');\n    const mask=await scene(600,400,[images(circle(300,200,180,'#fff'))],{transparentBase:true});\n    const cut=await painter.image.masking(src,mask,{type:'alpha'});\n    const gradient=await painter.image.gradientBlend(src,{type:'linear',angle:45,colors:[{stop:0,color:COLORS.blue},{stop:.5,color:COLORS.red},{stop:1,color:COLORS.gold}],blendMode:'screen'});\n    const tinted=await painter.image.colorsFilter(source,COLORS.teal,.38);\n    const keyed=await scene(600,400,[images(circle(300,200,180,COLORS.red))],{colorBg:'#00ff00'});await save('09-key-source.png',keyed);\n    const removed=await painter.image.colorsRemover(path.join(OUT,'09-key-source.png'),{red:0,green:255,blue:0});\n    const blended=await painter.image.blend([{image:cut,blendMode:'screen',opacity:.6,position:{x:0,y:0}},{image:removed,blendMode:'multiply',opacity:.6}],src);\n    const pts=[{x:40,y:40},{x:500,y:80},{x:570,y:320},{x:80,y:365}];\n    const crop=await painter.image.cropImage({imageSource:source,crop:'inner',radius:24,coordinates:pts.map((point,i) =>({from:point,to:pts[(i+1)%pts.length]}))});\n    const resized=await painter.image.resize({imagePath:src,size:{width:300,height:200},maintainAspectRatio:true,outputFormat:'png'});\n    const previews=[src,cut,gradient,tinted,blended,crop];\n    const names=['Original','Alpha mask','Gradient blend','Colour filter','Layer blend','Path crop'];\n    const layers=heading('09 / FINISHING','The image finishing desk','A practical asset pipeline, from procedural source to delivery formats.');\n    for(let i=0;i<previews.length;i++){const x=64+i%3*450,y=245+Math.floor(i/3)*335;layers.push({type:'imageBuffer',buffer:previews[i],x,y,width:410,height:273},textLayer(txt(names[i],x,y+286,19,COLORS.ink)));}\n    const palettes={};for(const method of ['kmeans','median-cut','octree'])palettes[method]=await painter.image.extractPalette(src,{method,count:7,format:'hex'});\n    palettes.kmeans.forEach((s,i) =>layers.push(images(rect(64+i*188,974,188,70,s.color)),textLayer(txt(s.color,64+i*188,1061,16,COLORS.ink,{font:font(16,'mono')}))));\n    const files=[await save('09-image-utilities.png',await scene(1440,1150,layers)),await save('09-alpha-cutout.png',cut),await save('09-color-key-cutout.png',removed),await save('09-resized.png',resized)];\n    for(const format of ['jpeg','webp','avif'])files.push(await save(`09-delivery.${format}`,await painter.image.compress(src,{format,quality:84,maxWidth:600})));\n    files.push(await save('09-converted.webp',await painter.image.imgConverter(src,'webp')));\n    const thumbs=await Promise.all(previews.map((imagePath) =>painter.image.resize({imagePath,size:{width:280,height:187},outputFormat:'png'})));\n    files.push(await save('09-stitch.png',await painter.image.stitchImages(thumbs,{direction:'horizontal',spacing:12})));\n    for(const type of ['grid','masonry','carousel'])files.push(await save(`09-collage-${type}.png`,await painter.image.createCollage(thumbs.map((source) =>({source})),{type,columns:3,spacing:14,background:COLORS.paper,borderRadius:14})));\n    files.push(await json('09-image-analysis.json',{palettes,colorAnalysis:await painter.image.colorAnalysis(source),validHex:painter.image.validHex(COLORS.red)}));return files;\n}"
