        "label": "Recipe 10",
        "language": "ts",
        "code": "import * as ApexRuntime from 'apexify.js';\nimport { mkdir, writeFile, readFile, access } from 'node:fs/promises';\nimport { fileURLToPath, pathToFileURL } from 'node:url';\nimport path from 'node:path';\nimport assert from 'node:assert/strict';\n\nconst Apex = ApexRuntime;\nconst ApexPainter = ApexRuntime.ApexPainter;\nconst ApexifyDecodeError = ApexRuntime.ApexifyDecodeError;\nconst painter = new ApexPainter({ type: 'buffer' });\n\n// This is the actual Peak Lab recipe.\n// Supporting drawing/chart/audio helpers used by this recipe are on the next code pages.\nasync function main() {\n  const growth=(t) =>8+83/(1+Math.exp(-(t-10)/2.7));\n    const a=series('Culture A',COLORS.red,growth),b=series('Culture B',COLORS.blue,(t) =>4+72/(1+Math.exp(-(t-13)/3.2)));\n    a.area={type:'around',show:true,color:COLORS.red,opacity:.14,lowerBound:a.data.map((d) =>d.y-5),upperBound:a.data.map((d) =>d.y+5)};\n    a.errorBar={show:true,color:COLORS.red,width:1.5,capSize:6};\n    a.data=a.data.map((d,i) =>({...d,errorBar:i%4===0?{positive:5,negative:5,show:true,color:COLORS.red,capSize:6}:undefined}));\n    const control=series('Control',COLORS.muted,(t) =>6+Math.sin(t*.4)*2);control.lineStyle='dashed';control.marker={show:false};\n    const opts=chartOptions('Cell density / synthetic experiment');opts.axes.x={...opts.axes.x,label:'Incubation time (h)',range:{min:0,max:24,step:4}};opts.axes.y={...opts.axes.y,label:'Relative density (%)',range:{min:0,max:110,step:20}};\n    return [await mountArt('10-line-chart.png',await painter.createChart('line',[a,b,control],opts),{title:'Growth under uncertainty',subtitle:'Synthetic data · envelope ±5 units · error bars every four hours'})];\n}"
