        "code": "const Apex = ApexRuntime;\nconst ApexPainter = ApexRuntime.ApexPainter;\nconst ApexifyDecodeError = ApexRuntime.ApexifyDecodeError;\n\n// ===== SHARED: studio =====\n\nconst ROOT = path.resolve(process.env.APEXIFY_OUTPUT_DIR || 'apexify-peak-output');\nconst OUT = path.join(ROOT, 'output');\nconst ASSETS = path.join(ROOT, 'assets');\nconst COLORS = Object.freeze({ ink:'#111827', paper:'#f4f0e8', muted:'#74808b', red:'#ee593b', teal:'#36d9b4', blue:'#5088ff', violet:'#bda5ff', gold:'#f1ba63', night:'#101820', panel:'#192630' });\nconst fontFile = (style='sans')  => path.join(ASSETS,'fonts',({sans:'DejaVuSans.ttf',bold:'DejaVuSans-Bold.ttf',serif:'DejaVuSerif.ttf',mono:'DejaVuSansMono.ttf'})[style]);\nconst font = (size=24,style='sans')  => ({size,path:fontFile(style),name:`Peak-${style}`,family:`Peak-${style}`});\nconst txt = (text,x,y,size=24,color=COLORS.ink,extra={})  => ({text,x,y,font:font(size),fill:{color},placement:{textBaseline:'top'},...extra});\nconst textLayer = (...texts[])  => ({type:'text',texts:texts.flat()});\nconst images = (...items[])  => ({type:'image',images:items.flat()});\nconst rect = (x,y,width,height,color,extra={})  => ({source:'rectangle',x,y,width,height,shape:{color},...extra});\nconst circle = (x,y,r,color,extra={})  => ({source:'circle',x:x-r,y:y-r,width:r*2,height:r*2,shape:{color},...extra});\nconst line = (points,color=COLORS.ink,width=1,extra={})  => ({type:'path',path:points.map(([x,y],i) =>({type:i?'lineTo':'moveTo',x,y})),options:{stroke:{color,width,lineJoin:'round',lineCap:'round'},...extra}});\nconst stops = (colors)  => colors.map((color,i) =>({stop:i/(colors.length-1),color}));\nconst linear = (colors,extra={})  => ({type:'linear',colors:stops(colors),...extra});\nconst radial = (colors,extra={})  => ({type:'radial',colors:stops(colors),...extra});\nconst conic = (colors,extra={})  => ({type:'conic',colors:stops(colors),...extra});\nconst rng = (seed=79)  => ()  => { seed=(Math.imul(1664525,seed)+1013904223)>>>0; return seed/4294967296; };\nconst polar = (cx,cy,r,a)  => [cx+Math.cos(a)*r,cy+Math.sin(a)*r];\nconst TAU = Math.PI*2;\nasync function save(name,buffer) : Promise<any> { await mkdir(OUT,{recursive:true}); await writeFile(path.join(OUT,name),buffer); return name; }\nasync function json(name,data) : Promise<any> { return save(name,JSON.stringify(data,null,2)+'\\n'); }\nasync function read(name) : Promise<any> { return readFile(path.join(OUT,name)); }\nasync function scene(width,height,layers,background={colorBg:COLORS.paper}) : Promise<any> { return painter.renderScene({width,height,background,layers}); }\nfunction heading(kicker,title,subtitle='',color=COLORS.ink,width=1440)  {\n  return [textLayer(txt(kicker.toUpperCase(),64,38,16,color,{font:font(16,'mono'),layout:{letterSpacing:2}}),txt(title,60,83,58,color,{font:font(58,'bold')}),txt(subtitle,64,159,18,color)),line([[64,202],[width-64,202]],color,1,{opacity:0.25})];\n}\nasync function mountArt(name,art,{title,subtitle='',width=1440,height=1040,dark=false}={}) : Promise<any> {\n  return save(name,await scene(width,height,[...heading('APEXIFY / PEAK LAB',title,subtitle,dark?COLORS.paper:COLORS.ink,width),{type:'imageBuffer',buffer:art,x:64,y:235,width:width-128,height:height-295}],{colorBg:dark?COLORS.night:COLORS.paper}));\n}\nasync function plate(w=960,h=640,phase=0) : Promise<any> {\n  // Generated source imagery: no downloads, no hidden stock-image dependency.\n  const layers=[];\n  for(let i=0;i<42;i++) {\n    const pts=Array.from({length:101},(_,j) =>{const x=j*w/100;return [x,h*.42+i*6+Math.sin(x/w*7+phase+i*.085)*h*.17+Math.sin(x/w*15-i*.12)*14];});\n    layers.push(line(pts,i%4===0?COLORS.gold:COLORS.teal,i%7===0?3:1,{opacity:.2+i/60}));\n  }\n  layers.push(images(circle(w*.72,h*.30,h*.21,COLORS.gold,{shape:{gradient:radial(['#fff5c8','#fa9e63','#962e56'],{startX:.25,startY:.2})}})));\n  return scene(w,h,layers,{gradientBg:linear(['#132c3d','#111320','#271a30'])});\n}"
