        "code": "import * as ApexRuntime from 'apexify.js';\nimport { mkdir, writeFile, readFile, access } from 'node:fs/promises';\nimport { fileURLToPath, pathToFileURL } from 'node:url';\nimport path from 'node:path';\nimport assert from 'node:assert/strict';\n\nconst Apex = ApexRuntime;\nconst ApexPainter = ApexRuntime.ApexPainter;\nconst ApexifyDecodeError = ApexRuntime.ApexifyDecodeError;\nconst painter = new ApexPainter({ type: 'buffer' });\n\n// This is the actual Peak Lab recipe.\n// Supporting drawing/chart/audio helpers used by this recipe are on the next code pages.\nasync function main() {\n  const random=rng(79),observations=Array.from({length:54},(_,i) =>({x:5+i*1.7,y:12+i*1.12+(random()-.5)*17}));\n    const scatter=await painter.createChart('scatter',[{label:'Synthetic observations',data:observations,color:COLORS.blue,markerSize:5,opacity:.7,correlation:{show:true,type:'linear',color:COLORS.red,lineWidth:3}}],{...chartOptions('Dose-response relationship'),axes:{x:{label:'Dose (arbitrary units)',color:COLORS.muted},y:{label:'Response (arbitrary units)',color:COLORS.muted}}});\n    const before=[series('Before',COLORS.blue,(t) =>18+Math.sin(t*.7)*12+t*.8)],after=[series('After',COLORS.red,(t) =>20+t*.9+Math.sin(t*.7)*3)];\n    const compare=await painter.createComparisonChart({dimensions:{width:1300,height:700},layout:'sideBySide',spacing:35,appearance:{backgroundColor:COLORS.paper},chart1:{type:'line',data:before,options:chartOptions('Uncontrolled process',600,620)},chart2:{type:'line',data:after,options:chartOptions('Stabilized process',600,620)}});\n    const combo=await painter.createComboChart({bars:Array.from({length:8},(_,i) =>({label:`R${i+1}`,xStart:i+.2,xEnd:i+.8,value:36+i*8,color:COLORS.teal,labelColor:COLORS.ink})),lines:[{...series('Yield (%)',COLORS.red,(i) =>63+i*3.6,8),data:Array.from({length:8},(_,i) =>({x:i+.5,y:63+i*3.6})),yAxis:'secondary'}],...chartOptions('Throughput and yield'),axes:{x:{showTickLabels:false,showTickMarks:false,color:COLORS.muted},y:{label:'Throughput (units/h)',range:{min:0,max:110,step:20},color:'#118e75'},ySecondary:{label:'Yield (%)',range:{min:50,max:100,step:10},color:COLORS.red}},legend:{show:false}});\n    return [await mountArt('13-scatter.png',scatter,{title:'Two explanations, one signal',subtitle:'Synthetic observations · computed linear fit · correlation does not establish causation'}),await mountArt('13-comparison.png',compare,{title:'A before / after study',subtitle:'Two independent chart panels composed with createComparisonChart'}),await mountArt('13-combo.png',combo,{title:'Throughput meets yield',subtitle:'Synthetic data · bars use the left axis · line uses the right axis'})];\n}"
