        "language": "ts",
        "code": "import * as ApexRuntime from 'apexify.js';\nimport { mkdir, writeFile, readFile, access } from 'node:fs/promises';\nimport { fileURLToPath, pathToFileURL } from 'node:url';\nimport path from 'node:path';\nimport assert from 'node:assert/strict';\n\nconst Apex = ApexRuntime;\nconst ApexPainter = ApexRuntime.ApexPainter;\nconst ApexifyDecodeError = ApexRuntime.ApexifyDecodeError;\nconst painter = new ApexPainter({ type: 'buffer' });\n\n// This is the actual Peak Lab recipe.\n// Supporting drawing/chart/audio helpers used by this recipe are on the next code pages.\nasync function main() {\n  const template=painter.createTemplate({width:600,height:780,background:{colorBg:COLORS.paper},layers:[\n      {type:'image',images:rect(0,0,600,780,'{{background}}')},\n      {id:'orb',type:'image',images:{source:'circle',x:100,y:178,width:400,height:400,shape:{gradient:linear([COLORS.red,COLORS.gold])}}},\n      {type:'text',texts:txt('PEAK / {{edition}}',36,37,16,'{{ink}}',{font:font(16,'mono')})},\n      {id:'title',type:'text',texts:txt('{{title}}',32,102,62,'{{ink}}',{font:font(62,'bold')})},\n      {type:'layout',x:36,y:584,width:528,height:60,layout:{type:'flex',direction:'row',gap:16,align:'center',justify:'space-between'},children:[\n        {type:'text',...txt('{{region}}',0,0,17,'{{ink}}')},{type:'text',...txt('{{year | 2042}}',0,0,17,'{{ink}}')}\n      ]},\n      {type:'layout',x:36,y:670,width:528,height:60,layout:{type:'grid',columns:3,gap:12,align:'center',justify:'start'},children:[\n        {type:'text',...txt('FIELD {{field}}',0,0,12,'{{ink}}',{font:font(12,'mono')})},{type:'text',...txt('ED. {{edition}}',0,0,12,'{{ink}}',{font:font(12,'mono')})},{type:'text',...txt('APEXIFY',0,0,12,'{{ink}}',{font:font(12,'mono')})}\n      ]},\n      {type:'text',visible:'{{limited}}',texts:txt('LIMITED / RESEARCH EDITION',36,747,12,'{{ink}}',{font:font(12,'mono')})}\n    ]});\n    const data=[{title:'SOLSTICE',region:'NORTHERN OBSERVATORY',background:COLORS.paper,ink:COLORS.ink,edition:'01',field:'A',limited:true},{title:'MIDNIGHT',region:'ARCTIC RESEARCH UNIT',background:COLORS.night,ink:COLORS.paper,edition:'02',field:'B',limited:false},{title:'VERDANT',region:'CANOPY FIELD STATION',background:'#143b37',ink:COLORS.paper,edition:'03',field:'C',limited:true},{title:'EQUINOX',region:'EQUATORIAL LAB',background:'#f5bb80',ink:COLORS.ink,edition:'04',field:'D',limited:false}];\n    const layers=heading('16 / TEMPLATE SYSTEMS','One system, four editions','The same immutable definition responds to data, overrides and layout.');const files=[];\n    for(let i=0;i<data.length;i++){\n      const options={overrides:{orb:{images:{shape:{gradient:linear([[COLORS.red,COLORS.gold],[COLORS.blue,COLORS.violet],[COLORS.teal,COLORS.gold],[COLORS.ink,COLORS.red]][i])}}}},insertions:[{targetId:'orb',position:'after',layers:{type:'image',images:circle(380,384,120,data[i].background)}}]};\n      const buf=await template.render(data[i],options);const name=`16-edition-${i+1}.png`;files.push(await save(name,buf));\n      layers.push({type:'imageBuffer',buffer:buf,x:64+i%2*675,y:240+Math.floor(i/2)*845,width:620,height:806});\n    }\n    const resolved=await template.toRenderInput(data[0]);\n    files.unshift(await save('16-templates.png',await scene(1440,1980,layers)));files.push(await json('16-template-resolved.json',resolved));return files;\n}"
