        "label": "Recipe 17",
        "language": "ts",
        "code": "import * as ApexRuntime from 'apexify.js';\nimport { mkdir, writeFile, readFile, access } from 'node:fs/promises';\nimport { fileURLToPath, pathToFileURL } from 'node:url';\nimport path from 'node:path';\nimport assert from 'node:assert/strict';\n\nconst Apex = ApexRuntime;\nconst ApexPainter = ApexRuntime.ApexPainter;\nconst ApexifyDecodeError = ApexRuntime.ApexifyDecodeError;\nconst painter = new ApexPainter({ type: 'buffer' });\n\n// This is the actual Peak Lab recipe.\n// Supporting drawing/chart/audio helpers used by this recipe are on the next code pages.\nasync function main() {\n  const host=makePainter(),photo=await plate(200,200);\n    host.assets.loadPalette('brand',{paper:COLORS.paper,ink:COLORS.ink,accent:COLORS.red});\n    host.assets.loadValue('edition',{number:79,density:90});\n    host.assets.loadImage('seal',photo).replaceImage('seal',photo);\n    host.assets.loadFont('heading',fontFile('bold')).replaceFont('heading',fontFile('bold'));\n    host.assets.replaceValue('edition',{number:79,density:100});\n    host.assets.replacePalette('brand',{paper:COLORS.paper,ink:COLORS.ink,accent:COLORS.red});\n    await host.use({name:'engraving',async install(painter): Promise<any> {\n      painter.plugins.use('engraving',{toLayers({cx,cy,radius,phase=0}) {\n        const accent=painter.assets.resolve('brand.accent');\n        return Array.from({length:80},(_,i) =>line(Array.from({length:140},(_,j) =>{\n          const u=j/139*2-1,x=u*radius;\n          return [cx+x,cy+(i-40)*5+Math.sin(u*4+phase+i*.035)*80*Math.sqrt(1-u*u)];\n        }),i%8===0?accent:'#68817b',i%8===0?2:.7,{opacity:.8}));\n      }});\n    }});\n    const api=host.plugins.get('engraving');\n    const layers=heading('17 / EXTENSION ARCHITECTURE','An extensible engraving engine','A trusted plugin builds normal scene layers and reads the caller’s named design tokens.');\n    layers.push(...api.toLayers({cx:710,cy:610,radius:580}),textLayer(txt('ENGRAVING / 079',64,926,18,COLORS.ink,{font:font(18,'mono')})));\n    const prepared=host.prepareForRender({width:1440,height:1010,background:{colorBg:'$brand.paper'},layers});\n    const art=await host.renderScene(prepared);\n    const report={assets:host.assets.list(),hasBrand:host.assets.has('brand'),installed:host.plugins.listInstalled(),isInstalled:host.plugins.isInstalled('engraving'),apis:host.plugins.list(),hasApi:host.plugins.has('engraving')};\n    // Alternate installation entry for applications managing their own host object.\n    await host.plugins.install({name:'editionStamp',install(target) {target.plugins.use('editionStamp',{number:79});}},host);\n    host.plugins.remove('editionStamp');host.plugins.remove('engraving');\n    host.assets.unregisterImage('seal').unregisterFont('heading').unregisterPalette('brand');host.assets.delete('edition');host.assets.clear();\n    return [await save('17-assets-and-plugins.png',art),await json('17-registry-report.json',report)];\n}"
