        "language": "ts",
        "code": "import * as ApexRuntime from 'apexify.js';\nimport { mkdir, writeFile, readFile, access } from 'node:fs/promises';\nimport { fileURLToPath, pathToFileURL } from 'node:url';\nimport path from 'node:path';\nimport assert from 'node:assert/strict';\n\nconst Apex = ApexRuntime;\nconst ApexPainter = ApexRuntime.ApexPainter;\nconst ApexifyDecodeError = ApexRuntime.ApexifyDecodeError;\nconst painter = new ApexPainter({ type: 'buffer' });\n\n// This is the actual Peak Lab recipe.\n// Supporting drawing/chart/audio helpers used by this recipe are on the next code pages.\nasync function main() {\n  const pairs=[[COLORS.red,COLORS.gold],[COLORS.blue,COLORS.violet],[COLORS.teal,'#215748'],[COLORS.ink,COLORS.muted],[COLORS.gold,COLORS.red],[COLORS.violet,COLORS.blue]];\n    const backgrounds=await painter.batch(pairs.map((colors) =>({type:'canvas',config:{width:390,height:520,gradientBg:linear(colors)}})));\n    const layers=heading('18 / AUTOMATED PRODUCTION','The identity printer','Six related compositions. Shared structure, independent data, stable output ordering.');\n    const files=[];\n    for(let i=0;i<6;i++){\n      const poster=await painter.chain([\n        {method:'createCanvas',args:[{width:390,height:520,colorBg:COLORS.paper}]},\n        {method:'createImage',args:[[{source:backgrounds[i],x:20,y:100,width:350,height:350,borderRadius:170},...Array.from({length:9},(_,j) =>circle(80+j*28,280+Math.sin(j*.6+i)*55,10+(j%3)*8,COLORS.paper,{opacity:.5}))],'current']},\n        {method:'createText',args:[[txt(`FIELD / ${String(i+1).padStart(2,'0')}`,24,26,17,COLORS.ink,{font:font(17,'mono')}),txt(['ORBIT','TIDAL','GROVE','NOIR','EMBER','ECHO'][i],24,60,46,COLORS.ink,{font:font(46,'bold')}),txt('GENERATIVE IDENTITY SERIES',24,474,13,COLORS.ink,{font:font(13,'mono')})],'current']}\n      ]);\n      files.push(await save(`18-identity-${i+1}.png`,poster));layers.push({type:'imageBuffer',buffer:poster,x:64+i%3*450,y:240+Math.floor(i/3)*595,width:414,height:552});\n    }\n    files.unshift(await save('18-batch-and-chain.png',await scene(1440,1450,layers)));return files;\n}"
