        "code": "import * as ApexRuntime from 'apexify.js';\nimport { mkdir, writeFile, readFile, access } from 'node:fs/promises';\nimport { fileURLToPath, pathToFileURL } from 'node:url';\nimport path from 'node:path';\nimport assert from 'node:assert/strict';\n\nconst Apex = ApexRuntime;\nconst ApexPainter = ApexRuntime.ApexPainter;\nconst ApexifyDecodeError = ApexRuntime.ApexifyDecodeError;\nconst painter = new ApexPainter({ type: 'buffer' });\n\n// This is the actual Peak Lab recipe.\n// Supporting drawing/chart/audio helpers used by this recipe are on the next code pages.\nasync function main() {\n  const master=await plate(1100,680),art=await scene(1440,980,[...heading('19 / OUTPUT PIPELINE','One master, every delivery','PNG master · encoded views · format-specific file exports'),{type:'imageBuffer',buffer:master,x:64,y:244,width:1312,height:675}]);\n    const dataURL=painter.output.dataURL(art),base64=painter.output.base64(art),blob=painter.output.blob(art),arrayBuffer=painter.output.arrayBuffer(art);\n    assert.deepEqual(Buffer.from(base64,'base64'),art);assert.deepEqual(Buffer.from(await blob.arrayBuffer()),art);assert.deepEqual(Buffer.from(arrayBuffer),art);\n    const chosen=makePainter({type:'dataURL'});assert.equal(await chosen.toOutput(art),dataURL);assert.equal(await chosen.outPut(art),dataURL); // Explicit deprecated alias compatibility example.\n    const png=await painter.save(art,{directory:OUT,filename:'19-output.png',naming:'custom',format:'png',overwrite:true});\n    const set=await painter.saveMultiple([art,master],{directory:OUT,prefix:'19-delivery-',naming:'counter',counterStart:1,format:'webp',quality:86,overwrite:true});\n    return [path.basename(png.path),...set.map((x) =>path.basename(x.path)),await json('19-output-formats.json',{pngBytes:art.length,base64Characters:base64.length,blobType:blob.type,arrayBufferBytes:arrayBuffer.byteLength,configuredType:chosen.outputFormat.type,byteEquivalence:true})];\n}"
