        "code": "function parseWav(buffer) {\n  if(buffer.toString('ascii',0,4)!=='RIFF'||buffer.toString('ascii',8,12)!=='WAVE')throw new Error('Expected PCM WAV');\n  let channels,sampleRate,bits,data;\n  for(let at=12;at+8<=buffer.length;){\n    const id=buffer.toString('ascii',at,at+4),length=buffer.readUInt32LE(at+4),start=at+8;\n    if(id==='fmt '){channels=buffer.readUInt16LE(start+2);sampleRate=buffer.readUInt32LE(start+4);bits=buffer.readUInt16LE(start+14);}\n    if(id==='data')data=buffer.subarray(start,start+length);\n    at=start+length+(length%2);\n  }\n  if(!data||bits!==16)throw new Error('Expected PCM16 WAV data');\n  const frames=data.length/(2*channels);let peak=0,sum=0;\n  for(let i=0;i<data.length;i+=2){const v=data.readInt16LE(i)/32768;peak=Math.max(peak,Math.abs(v));sum+=v*v;}\n  return {channels,sampleRate,frames,duration:frames/sampleRate,peak,rms:Math.sqrt(sum/(data.length/2)),data};\n}\nfunction waveform(wav,width=1000,channel=0) {\n  const data=parseWav(wav),bins=[];\n  for(let x=0;x<width;x++){\n    const from=Math.floor(x*data.frames/width),to=Math.max(from+1,Math.floor((x+1)*data.frames/width));let min=0,max=0;\n    for(let i=from;i<to;i++){const n=(i*data.channels+Math.min(channel,data.channels-1))*2;if(n+2>data.data.length)break;const v=data.data.readInt16LE(n)/32768;min=Math.min(min,v);max=Math.max(max,v);}\n    bins.push({min,max});\n  }return bins;\n}"
