        "code": "import * as ApexRuntime from 'apexify.js';\nimport { mkdir, writeFile, readFile, access } from 'node:fs/promises';\nimport { fileURLToPath, pathToFileURL } from 'node:url';\nimport path from 'node:path';\nimport assert from 'node:assert/strict';\n\nconst Apex = ApexRuntime;\nconst ApexPainter = ApexRuntime.ApexPainter;\nconst ApexifyDecodeError = ApexRuntime.ApexifyDecodeError;\nconst painter = new ApexPainter({ type: 'buffer' });\n\n// This is the actual Peak Lab recipe.\n// Supporting drawing/chart/audio helpers used by this recipe are on the next code pages.\nasync function main() {\n  const width=640,height=480,count=40,callbacks=[];\n    const frames=Array.from({length:count},(_,frame) =>({backgroundColor:COLORS.night,duration:80,width,height,onDrawCustom(ctx) {\n      const phase=frame/count*TAU;ctx.translate(width/2,height/2);\n      for(let i=0;i<90;i++){\n        const a=i/90*TAU,rad=155+Math.sin(a*6+phase)*22;\n        const b=a+1.8+.25*Math.sin(phase),end=170+Math.cos(b*4-phase)*20;\n        ctx.beginPath();ctx.moveTo(Math.cos(a)*rad,Math.sin(a)*rad);\n        ctx.bezierCurveTo(Math.cos(a+phase)*40,Math.sin(a+phase)*40,Math.cos(b-phase)*60,Math.sin(b-phase)*60,Math.cos(b)*end,Math.sin(b)*end);\n        ctx.strokeStyle=i%4?`rgba(54,217,180,0.3)`:'rgba(241,186,99,0.8)';ctx.lineWidth=i%4?1:1.7;ctx.stroke();\n      }\n      ctx.setTransform(1,0,0,1,0,0);ctx.fillStyle=COLORS.paper;ctx.font='16px monospace';ctx.fillText('KINETIC LOOM / APEXIFY',24,33);\n    }}));\n    const paths=await painter.animate(frames,80,width,height,{onStart:() =>callbacks.push('start'),onFrame:(i) =>callbacks.push(i),onEnd:() =>callbacks.push('end')});\n    const result=await painter.createGIF(paths.map((buffer) =>({buffer,duration:80})),{outputFormat:'buffer',width,height,repeat:0,quality:5});\n    return [await save('23-animate.gif',result),await save('23-animate-poster.png',paths[8]),await json('23-animate-callbacks.json',callbacks)];\n}"
