        "label": "Recipe 24",
        "language": "ts",
        "code": "import * as ApexRuntime from 'apexify.js';\nimport { mkdir, writeFile, readFile, access } from 'node:fs/promises';\nimport { fileURLToPath, pathToFileURL } from 'node:url';\nimport path from 'node:path';\nimport assert from 'node:assert/strict';\n\nconst Apex = ApexRuntime;\nconst ApexPainter = ApexRuntime.ApexPainter;\nconst ApexifyDecodeError = ApexRuntime.ApexifyDecodeError;\nconst painter = new ApexPainter({ type: 'buffer' });\n\n// This is the actual Peak Lab recipe.\n// Supporting drawing/chart/audio helpers used by this recipe are on the next code pages.\nasync function main() {\n  try{await access(path.join(OUT,'21-signal-archive.wav'));}catch{await recipe21.run();}\n    const fps=24,count=144,width=960,height=540,frames=[];\n    for(let i=1;i<count;i++)frames.push(await renderMotion(i/count,width,height));\n    const raw=path.join(OUT,'24-motion-source.mp4');\n    await painter.renderSceneToVideoFrames(motionScene(0,width,height),{options:{source:frames[0],createFromFrames:{frames,outputPath:raw,fps,quality:'high',format:'mp4'}}});\n    const sceneGif=await painter.renderSceneToGIF(motionScene(0,480,270),{options:{outputFormat:'buffer',width:480,height:270,repeat:0,delay:200,quality:5},gifFrames:await Promise.all([.15,.3,.45,.6,.75,.9].map(async (t): Promise<any> =>({buffer:await renderMotion(t,480,270),duration:200}))),composedFrameDuration:200});\n    const pipeline=painter.videoPipeline(raw);\n    pipeline.trim(0,6,'final-duration');\n    pipeline.text({...txt('A FIELD IN MOTION',40,471,19,COLORS.paper,{font:font(19,'mono')}),startTime:.2,endTime:5.7,transitionIn:{type:'fade',duration:.5},transitionOut:{type:'fade',duration:.5}},'closing-line');\n    pipeline.audio({type:'file',source:path.join(OUT,'21-signal-archive.wav'),startTime:0,duration:6,volume:.75,fadeOut:1.2},{keepOriginalAudio:false,durationPolicy:'video'},'score');\n    const canUndo=pipeline.canUndo();pipeline.undo();const canRedo=pipeline.canRedo();pipeline.redo();\n    const snapshot=pipeline.toJSON();\n    const outputPath=path.join(OUT,'24-film.mp4');\n    const result=await pipeline.render({outputPath,preset:'export',overwrite:true});\n    const info=await painter.getVideoInfo(outputPath);\n    const single=await painter.extractFrameAtTime(outputPath,2.5,'png'),numbered=await painter.extractFrameByNumber(outputPath,49,'png'),multiple=await painter.extractMultipleFrames(outputPath,[1,3,5],'png');\n    const interval=await painter.extractFrames(outputPath,{interval:2000,outputDirectory:path.join(OUT,'24-interval-frames'),outputFormat:'png'});\n    const all=await painter.extractAllFrames(outputPath,{startTime:0,endTime:.125,outputDirectory:path.join(OUT,'24-first-frames'),outputFormat:'png'});\n    const edit=painter.videoPipeline().source(raw);edit.pushLayer({kind:'trim',id:'working-trim',startTime:0,endTime:4}).removeLayer('working-trim');edit.splice({targetStartTime:1,targetEndTime:1.5,replacementFrames:[frames[0]],replacementFps:2},'insert').clearLayers('splice');\n    const rebuilt=painter.videoPipeline(undefined,snapshot.layers);const restored=rebuilt.getLayers().length;\n    return ['24-film.mp4','24-motion-source.mp4',await save('24-scene.gif',sceneGif),await save('24-film-poster.png',single),await save('24-frame-49.png',numbered),...await Promise.all(multiple.map((buf,i) =>save(`24-frame-at-${[1,3,5][i]}s.png`,buf))),await json('24-film-report.json',{info,result,history:{canUndo,canRedo,restoredLayers:restored},intervalFrames:interval.length,firstFrames:all.length}),await json('24-pipeline.json',snapshot)];\n}"
