        "label": "Helpers · Motion",
        "language": "ts",
        "code": "function motionScene(t,width=800,height=450) {\n  const scale=width/800,cx=width*.58,cy=height*.57,layers=[];\n  for(let k=0;k<16;k++){\n    const radius=(45+k*9)*scale;\n    const pts=Array.from({length:121},(_,i) =>{\n      const a=i/120*TAU,r=radius*(1+.12*Math.sin(3*a+t*TAU+k*.12));\n      return [cx+Math.cos(a)*r,cy+Math.sin(a)*r*.62];\n    });\n    layers.push(line(pts,k%4?COLORS.teal:COLORS.gold,k%4?.8:1.6,{opacity:.3+k/25}));\n  }\n  layers.push(images(circle(cx,cy,44*scale,COLORS.gold,{shape:{gradient:radial(['#ffe8b7',COLORS.red,'#482045'])}})));\n  const particles=[];\n  for(let k=0;k<30;k++){const a=k/30*TAU+t*TAU,r=(155+Math.sin(k*7)*28)*scale;particles.push(circle(cx+Math.cos(a)*r,cy+Math.sin(a)*r*.62,(1.8+k%3)*scale,k%3?COLORS.teal:COLORS.gold));}\n  layers.push(images(particles),textLayer(txt('APEXIFY / MOTION STUDY',34*scale,30*scale,13*scale,COLORS.teal,{font:font(13*scale,'mono')}),txt('ORBITAL',31*scale,70*scale,52*scale,COLORS.paper,{font:font(52*scale,'bold')}),txt('RESONANCE',34*scale,127*scale,18*scale,COLORS.paper,{layout:{letterSpacing:3*scale}}),txt('PROCEDURAL FIELD 079',34*scale,height-40*scale,11*scale,COLORS.teal,{font:font(11*scale,'mono')})));\n  return {width,height,background:{gradientBg:linear(['#0d202c','#102728','#201a27'])},layers};\n}\nconst renderMotion=(t,w=800,h=450) =>painter.renderScene(motionScene(t,w,h));"
