        "label": "Recipe 25 · 2/2",
        "language": "ts",
        "code": "      ['addTextOverlay',{overlays:[{...txt('SYNTHETIC SIGNAL',42,260,38,COLORS.paper,{font:font(38,'bold')}),startTime:.3,endTime:4,transitionIn:{type:'slideUp',duration:.5},transitionOut:{type:'fade',duration:.5}}],outputPath:output('timed-type')}],\n      ['addAnimatedText',{text:'LEGACY MOTION',animation:'slideIn',startTime:.3,endTime:4,position:{x:40,y:280},fontSize:28,outputPath:output('legacy-animated-text')}]\n    ];\n    const report=[],files=[];\n    for(const [operation,options] of cases){\n      const begin=performance.now();\n      try{\n        const result=await painter.createVideo({source,[operation]:options,timeoutMs:90000,overwrite:true});\n        let info;\n        if(/\\.(mp4|webm)$/.test(options?.outputPath ?? '')){info=await painter.getVideoInfo(options.outputPath);files.push(path.relative(OUT,options.outputPath));}\n        if(operation==='generateThumbnail'){const buffer=Buffer.isBuffer(result)?result:result.buffer;if(buffer)files.push(await save('25-thumbnail-sheet.png',buffer));}\n        report.push({operation,status:'passed',seconds:Math.round((performance.now()-begin)/10)/100,...(info?{duration:info.duration,width:info.width,height:info.height,audio:info.audio}:{})});\n      }catch(error){\n        report.push({operation,status:'failed',error:error.message,code:error.code,cause:error.cause?.message});\n        console.error(`25 / ${operation}: ${error.message}`);\n      }\n    }\n    const layers=heading('25 / MEDIA OPERATIONS','The complete video workbench','Each row records a real call. Failures stay visible in the accompanying report.');\n    for(let i=0;i<report.length;i++){const item=report[i],x=64+i%3*450,y=247+Math.floor(i/3)*73;layers.push(images(rect(x,y,414,55,item.status==='passed'?'#e1eadf':'#f8d8cf',{borderRadius:8})),textLayer(txt(item.status==='passed'?'OK':'ERR',x+13,y+17,16,item.status==='passed'?'#178574':COLORS.red,{font:font(16,'mono')}),txt(item.operation,x+67,y+17,16,COLORS.ink,{font:font(16,'mono')})));}\n    files.unshift(await save('25-video-workbench.png',await scene(1440,280+Math.ceil(report.length/3)*73,layers)));\n    files.push(await json('25-video-operations.json',report));\n    const failed=report.filter((item) =>item.status==='failed');\n    if(failed.length)throw new Error(`Video workbench failed ${failed.length} operation(s): ${failed.map((item) =>item.operation).join(', ')}`);\n    return files;\n}"
