        "code": "import * as ApexRuntime from 'apexify.js';\nimport { mkdir, writeFile, readFile, access } from 'node:fs/promises';\nimport { fileURLToPath, pathToFileURL } from 'node:url';\nimport path from 'node:path';\nimport assert from 'node:assert/strict';\n\nconst Apex = ApexRuntime;\nconst ApexPainter = ApexRuntime.ApexPainter;\nconst ApexifyDecodeError = ApexRuntime.ApexifyDecodeError;\nconst painter = new ApexPainter({ type: 'buffer' });\n\n// This is the actual Peak Lab recipe.\n// Supporting drawing/chart/audio helpers used by this recipe are on the next code pages.\nasync function main() {\n  const width=1800,height=1280,n=24,m=22,random=rng(1979),layers=[];\n    const project=(x,y,z=0) =>({x:766+(x-y)*24,y:338+(x+y)*12-z});\n    const polygon=(points,color,stroke) =>({type:'path',path:[{type:'polygon',points}],options:{fill:{color},...(stroke?{stroke:{color:stroke,width:.7}}:{})}});\n    layers.push(polygon([project(-1,-1),project(n+1,-1),project(n+1,m+1),project(-1,m+1)],'#cbded6'));\n    for(let x=0;x<=n;x++)layers.push(line([Object.values(project(x,0)),Object.values(project(x,m))],'#ebeee5',1));\n    for(let y=0;y<=m;y++)layers.push(line([Object.values(project(0,y)),Object.values(project(n,y))],'#ebeee5',1));\n    let buildings=0;\n    for(let diagonal=0;diagonal<n+m;diagonal++)for(let x=0;x<n;x++){\n      const y=diagonal-x;if(y<0||y>=m||x%7===0||y%6===0)continue;\n      const hill=Math.exp(-((x-13)**2+(y-10)**2)/95),z=18+hill*145+random()*47;\n      const a=project(x+.13,y+.13),b=project(x+.87,y+.13),c=project(x+.87,y+.87),d=project(x+.13,y+.87);\n      const at=project(x+.13,y+.13,z),bt=project(x+.87,y+.13,z),ct=project(x+.87,y+.87,z),dt=project(x+.13,y+.87,z);\n      const hero=hill>.72&&random()>.57;\n      layers.push(polygon([bt,b,c,ct],hero?'#a53d36':'#397f7a'),polygon([dt,ct,c,d],hero?'#d96d43':'#6eaaa0'),polygon([at,bt,ct,dt],hero?'#ffcb7e':'#c3ead4','#99beae'));\n      if(z>135&&buildings%4===0){const top=project(x+.5,y+.5,z);layers.push(line([[top.x,top.y],[top.x,top.y-18]],'#304e4d',1),images(circle(top.x,top.y-19,2,COLORS.red)));}\n      buildings++;\n    }\n    const baseCity=await scene(width,height,layers,{colorBg:COLORS.paper});\n    const curve=[series('Demand',COLORS.red,(t) =>42+Math.sin(t*.32)*24+t*.5,24),series('Renewables','#138878',(t) =>54+Math.sin(t*.27-1)*21,24)];\n    const chart=await painter.createChart('line',curve,{...chartOptions('24 HOUR ENERGY PROFILE',390,300),axes:{x:{color:COLORS.muted,range:{min:0,max:24,step:6}},y:{color:COLORS.muted,range:{min:0,max:100,step:25}}},legend:{show:false}});\n    const annotation=[...heading('26 / APEXIFY INTEGRATED SHOWCASE','Aster / a city made of signals','An original procedural city, generated entirely through the public Node APIs.',COLORS.ink,width),\n      {type:'imageBuffer',buffer:chart,x:1340,y:620,width:395,height:300},\n      textLayer(txt('SYNTHETIC\\nURBAN SYSTEM',1349,290,25,COLORS.ink,{font:font(25,'bold'),layout:{lineHeight:1.2}}),txt(String(buildings),1343,378,104,COLORS.red,{font:font(104,'bold')}),txt('PROCEDURAL BUILDINGS',1350,495,15,COLORS.muted,{font:font(15,'mono')}),txt('A 24 × 22 spatial field, projected\\ninto two dimensions. Every roof,\\nwall, street and signal is code.',1350,540,17,COLORS.ink,{layout:{lineHeight:1.6}}),txt('FORM FOLLOWS DATA.',64,1138,46,COLORS.ink,{font:font(46,'serif')}),txt('APEXIFY / PEAK LAB / 026',64,1220,16,COLORS.muted,{font:font(16,'mono')})),\n      ...painter.components.progressBar.toLayers({x:1350,y:966,width:365,height:16,value:78,max:100,fill:'#168c78',background:'#d7ddd4',radius:6}),textLayer(txt('SIMULATED RENEWABLE SHARE',1350,930,13,COLORS.muted,{font:font(13,'mono')}),txt('78%',1350,1009,61,'#168c78',{font:font(61,'bold')}))\n    ];\n    const final=await scene(width,height,[{type:'imageBuffer',buffer:baseCity,x:0,y:0},...annotation]);\n    return [await save('26-capstone.png',final),await json('26-city-metadata.json',{buildings,grid:{x:n,y:m},projection:'2.5D isometric, generated application geometry',data:'synthetic',apis:['renderScene','createChart','components.progressBar.toLayers']})];\n}"
